import {journal,worksheet} from './journal.js';
import {meta,sources,lessons,studies,drugs,protocols,timeline,glossary} from './content.js';
import {questions,cases,cards} from './learning.js';
import {normalize,searchContent,calcRisk,calcBody,schedules,makeSchedule,nextReview,escapeHtml as e} from './core.js';
const root=document.querySelector('#app');
const key='incretina-learning-v1';
const blank=()=>({completed:[],bookmarks:[],notes:{},reviews:{},answers:{},last:lessons[0].id});
let state;try{state={...blank(),...JSON.parse(localStorage.getItem(key)||'{}')};if(!Array.isArray(state.completed)||!Array.isArray(state.bookmarks)||!state.notes||typeof state.notes!=='object'||!state.reviews||typeof state.reviews!=='object'||!state.answers||typeof state.answers!=='object')state=blank()}catch{state=blank()}
let route='',filter='Todos',mobile=false,quizSession=null,flashId=null,flipped=false,chat=[],apiReady=null,chatBusy=false;
const idx=[...lessons.map(x=>({id:x.id,type:'Aula',title:x.title,text:JSON.stringify(x),url:'#aula/'+x.id})),...studies.map(x=>({id:x.id,type:'Estudo',title:x.name+' · '+x.title,text:JSON.stringify(x),url:'#estudo/'+x.id})),...drugs.map(x=>({id:x.id,type:'Medicamento',title:x.name+' · '+x.brands,text:JSON.stringify(x),url:'#farmaco/'+x.id})),...protocols.map(x=>({id:x.id,type:'Protocolo',title:x.title,text:JSON.stringify(x),url:'#protocolo/'+x.id}))];
const sourceMap=Object.fromEntries(sources.map(x=>[x.id,x]));
const fmt=(n,d=1)=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:d,minimumFractionDigits:d});
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC'});
const refs=ids=>`<div class="source-links">${[...new Set(ids)].map(id=>sourceMap[id]?`<a href="${e(sourceMap[id].url)}" target="_blank" rel="noopener noreferrer" title="${e(sourceMap[id].note)}">${e(sourceMap[id].title)} ↗</a>`:'').join('')}</div>`;
const tag=(s,c='')=>`<span class="tag ${c}">${e(s)}</span>`;
const head=(eyebrow,title,subtitle='',action='')=>`<div class="page-head"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1>${subtitle?`<p>${e(subtitle)}</p>`:''}</div>${action}</div>`;
const btn=(text,url,cls='')=>`<a class="btn ${cls}" href="${url}">${text}</a>`;
const categories=items=>['Todos',...new Set(items.map(x=>x.category||x.topic))];
const filters=items=>`<div class="filters" aria-label="Filtrar conteúdo">${categories(items).map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${e(x)}" aria-pressed="${filter===x}">${e(x)}</button>`).join('')}</div>`;
const filtered=items=>filter==='Todos'?items:items.filter(x=>(x.category||x.topic)===filter);
const icon={inicio:'◫',trilhas:'▤',farmacos:'⊕',estudos:'◈',protocolos:'☷',casos:'◇',revisao:'▣',ferramentas:'⊞',tutor:'✧',biblioteca:'⌑',caderno:'✎'};
const nav=[['inicio','Visão geral'],['trilhas','Trilha de aprendizagem'],['farmacos','Medicamentos'],['estudos','Estudos destrinchados'],['protocolos','Protocolos clínicos'],['casos','Casos & avaliação'],['revisao','Revisão espaçada'],['ferramentas','Ferramentas'],['tutor','Tutor IA'],['biblioteca','Referências & glossário'],['caderno','Meu caderno']];
function group(r){return ({aula:'trilhas',farmaco:'farmacos',estudo:'estudos',protocolo:'protocolos',caso:'casos',quiz:'casos',historia:'trilhas'})[r]||r}
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Não foi possível salvar neste navegador. Use a exportação do caderno.')}}
function toast(text){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=text;document.body.append(t);setTimeout(()=>t.remove(),4500)}
function shell(content){const active=group(route.split('/')[0]);root.innerHTML=`<aside class="sidebar ${mobile?'open':''}" aria-label="Navegação principal"><a class="brand" href="#inicio"><img src="icon.svg" alt=""><div><strong>incretina</strong><small>ACADEMIA MÉDICA</small></div></a><div class="nav-label">SEU ESPAÇO DE ESTUDO</div><nav>${nav.map(([id,title])=>`<a href="#${id}" class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon[id]}</span>${title}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="profile"><div class="avatar">MD</div><div>Aprendizagem médica<br><small class="muted" style="color:#b8ccbe">Progresso neste dispositivo</small></div></div><p>GLP-1 · GIP · Terapias metabólicas<br>Edição ${meta.version}</p></div></aside><div class="shell"><header class="topbar"><button class="mobile-menu" aria-label="Abrir menu" aria-expanded="${mobile}" data-action="menu">☰</button><div class="breadcrumb">Academia <span class="muted">/ ${e(nav.find(x=>x[0]===active)?.[1]||'Estudo')}</span></div><form class="search" id="search-form" role="search"><input id="global-search" aria-label="Buscar aulas, estudos e medicamentos" placeholder="Buscar tema, medicamento ou estudo..." autocomplete="off"><div id="search-results" class="search-results hide"></div></form><span class="top-tag">Edição · setembro 2026</span></header><main class="main" id="main" tabindex="-1">${content}<footer class="footer">${e(meta.editorial)} <a href="#biblioteca">Fontes e limites desta edição</a>.<br>Progresso e anotações ficam neste navegador. Não insira dados identificáveis de pacientes.</footer></main></div>`;bindGlobal()}
function moduleCard(x,i){const done=state.completed.includes(x.id);return `<a class="module" href="#aula/${x.id}"><div class="module-top"><span class="module-num">${String(i+1).padStart(2,'0')}</span>${tag(x.category)}</div><h3>${e(x.title)}</h3><p>${e(x.summary)}</p><div class="module-footer"><span>${done?'✓ Concluída':x.sections.length+' tópicos'}</span><span>${done?'Revisar':'Estudar'} ↗</span></div></a>`}
function dashboard(){const progress=Math.round(state.completed.length/lessons.length*100),current=lessons.find(x=>x.id===state.last&&!state.completed.includes(x.id))||lessons.find(x=>!state.completed.includes(x.id))||lessons[0];const due=cards.filter(c=>!state.reviews[c.id]||state.reviews[c.id].due<=Date.now()).length;return head('Aprendizagem baseada em evidências','Seu próximo passo na medicina metabólica.','Da fisiologia ao raciocínio clínico. Estude no seu ritmo e consulte o que precisa.',btn('Meu caderno','#caderno'))+`<div class="stats"><div class="stat"><strong>${lessons.length}</strong><span>Aulas na trilha</span></div><div class="stat"><strong>${studies.length}</strong><span>Estudos comentados</span></div><div class="stat"><strong>${drugs.length}</strong><span>Fichas de medicamentos</span></div><div class="stat"><strong>${cases.length} + ${questions.length}</strong><span>Casos e questões</span></div></div><div class="dash-grid"><div><section class="feature"><div class="eyebrow">${state.completed.length?'Continue de onde parou':'COMECE PELA BASE'} · AULA ${String(lessons.indexOf(current)+1).padStart(2,'0')}</div><h2>${e(current.title)}</h2><p>${e(current.summary)}</p><div class="feature-foot">${btn(state.completed.length?'Continuar aula →':'Começar a estudar →','#aula/'+current.id,'lime')}<span>${current.sections.length} tópicos · leitura + aplicação</span></div></section><div class="section-head"><h2>Uma trilha, do fundamento à prática</h2><a href="#trilhas">Ver todas as aulas ↗</a></div><div class="module-grid">${lessons.slice(0,4).map(moduleCard).join('')}</div><div class="section-head"><h2>Leia o resultado. Entenda o limite.</h2><a href="#estudos">Todos os estudos ↗</a></div>${studyCard(studies.find(x=>x.id==='surmount5'))}</div><aside class="dash-side"><section class="panel"><div class="eyebrow">Seu progresso</div><div class="progress-big">${progress}<span style="font-size:20px">%</span></div><div class="progress-track" role="progressbar" aria-label="Progresso na trilha" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100"><div style="width:${progress}%"></div></div><p>${state.completed.length} de ${lessons.length} aulas concluídas.<br>O conhecimento cresce com a revisão.</p>${btn('Revisar '+due+' cartões','#revisao','small full')}</section><section class="panel"><div class="eyebrow">Acesso rápido</div><ul class="compact-list"><li><a href="#farmaco/tirzepatida">Tirzepatida<small>Dose inicial, escalonamento e cuidados</small></a></li><li><a href="#protocolo/vomitos">Sintomas gastrointestinais<small>Reconhecer sinais de alarme</small></a></li><li><a href="#ferramentas">Benefício absoluto<small>Calcule ARR e NNT</small></a></li></ul></section><section class="panel" style="background:#e8efdf"><div class="row">${tag('Tutor de estudo')}<span aria-hidden="true">✧</span></div><h3 style="margin-top:16px">Uma dúvida no caminho?</h3><p>Explore a biblioteca e peça explicações com fontes quando a IA estiver ativada.</p>${btn('Abrir tutor','#tutor','small')}</section><section class="panel"><div class="eyebrow">Leitura responsável</div><p>Fontes internacionais identificadas. Confira bula brasileira e limites antes de aplicar à prática.</p><a href="#biblioteca" style="font-size:13px">Ver método editorial ↗</a></section></aside></div>`}
function trail(){return head('Currículo','Trilha de aprendizagem','Siga a sequência ou escolha um tema. A conclusão é registrada por você.',btn('Linha do tempo','#historia'))+filters(lessons)+`<div class="module-grid">${filtered(lessons).map(x=>moduleCard(x,lessons.indexOf(x))).join('')}</div>`}
function lessonPage(id){const x=lessons.find(x=>x.id===id);if(!x)return missing();state.last=id;persist();return `<div class="content-grid"><article class="article"><div class="row">${btn('← Trilha','#trilhas','small')}${tag(x.category)}${tag('Aula '+String(lessons.indexOf(x)+1).padStart(2,'0'))}</div><h1>${e(x.title)}</h1><p class="lead">${e(x.summary)}</p><section class="notice info"><strong>Ao terminar, você deverá conseguir:</strong><ul>${x.objectives.map(o=>`<li>${e(o)}</li>`).join('')}</ul></section>${x.sections.map((s,i)=>`<section id="sec-${i}"><h2>${e(s.title)}</h2><p>${e(s.text)}</p></section>`).join('')}<blockquote>${e(x.takeaway)}</blockquote><h2>Referências para aprofundar</h2>${refs(x.refs)}<p class="saved-note">Síntese educacional. Os links de fonte indicam o que foi consultado e suas limitações.</p>${noteBox('aula/'+id)}<div class="reading-actions"><button class="btn primary" data-complete="${id}">${state.completed.includes(id)?'✓ Concluída · desfazer':'Marcar aula como concluída'}</button>${lessons[lessons.indexOf(x)+1]?btn('Próxima aula →','#aula/'+lessons[lessons.indexOf(x)+1].id):btn('Aplicar em casos →','#casos')}</div></article><aside class="panel toc"><div class="eyebrow">Nesta aula</div>${x.sections.map((s,i)=>`<a href="#sec-${i}" data-scroll="sec-${i}">${e(s.title)}</a>`).join('')}<hr style="border:0;border-top:1px solid var(--line)">${bookmark('aula/'+id)}<button class="btn small full" data-ask="Explique o tema: ${e(x.title)}" style="margin-top:12px">Perguntar ao tutor ✧</button><button class="btn small full" data-action="print" style="margin-top:12px">Imprimir / salvar PDF</button></aside></div>`}
function bookmark(id){return `<button class="btn small full" data-bookmark="${id}">${state.bookmarks.includes(id)?'★ Salvo no caderno':'☆ Salvar no caderno'}</button>`}
function noteBox(id){return `<section class="no-print"><label class="field">Minhas anotações<textarea data-note="${id}" maxlength="20000" placeholder="Registre uma ideia, dúvida ou aplicação. Não inclua dados de pacientes.">${e(state.notes[id]||'')}</textarea></label><span class="saved-note">Salvas automaticamente neste navegador.</span></section>`}
function studyCard(s){return `<a class="study-card" href="#estudo/${s.id}"><div><div class="row">${tag(s.topic)}<span class="eyebrow" style="letter-spacing:1px">${s.year}</span></div><h3>${e(s.name)}</h3><p>${e(s.title)}</p></div><div class="study-result"><strong>${e(s.metric)}</strong><small>${e(s.metricLabel)}</small></div></a>`}
function studyList(){return head('Clube de revista','Estudos destrinchados','População, intervenção, resultado e limites. Leituras regulatórias estão identificadas.')+filters(studies)+filtered(studies).map(studyCard).join('')}
function comparison(s){if(!s.comparison)return '';const c=s.comparison,max=Math.max(c.treatment,c.control)*1.15;return `<section class="bar-compare"><div class="eyebrow">${e(c.label)}</div>${[['treatment','treatmentName',''],['control','controlName','control']].map(([v,l,cl])=>`<div class="bar-line"><div class="bar-label"><span>${e(c[l])}</span><strong>${fmt(c[v])}%</strong></div><div class="bar ${cl}" style="width:${c[v]/max*100}%"></div></div>`).join('')}<small class="muted">Comparação dentro do mesmo estudo. Escala linear, origem em zero.</small></section>`}
function studyPage(id){const s=studies.find(x=>x.id===id);if(!s)return missing();return `<div class="content-grid"><article class="article"><div class="row">${btn('← Estudos','#estudos','small')}${tag(s.topic)}${tag(String(s.year))}</div><h1>${e(s.name)}</h1><p class="lead">${e(s.title)}</p><div class="metrics"><div class="metric"><strong>${e(s.metric)}</strong><span>${e(s.metricLabel)}</span></div><div class="metric"><strong>${s.year}</strong><span>Ano de referência do estudo</span></div><div class="metric"><strong>${s.comparison?'Direta':'PICO'}</strong><span>${s.comparison?'Comparação do ensaio':'Pergunta e contexto'}</span></div></div>${comparison(s)}<h2>Quem foi estudado?</h2><p>${e(s.population)}</p><h2>Como o estudo foi feito?</h2><p>${e(s.design)}</p><h2>O que foi comparado?</h2><p>${e(s.intervention)}</p><h2>O que mudou?</h2><p>${e(s.result)}</p><div class="notice"><strong>Onde a conclusão termina</strong><p style="margin-bottom:0">${e(s.limitations)}</p></div><h2>O que isso muda na prática?</h2><p>${e(s.practice)}</p>${journalPanel(s)}<h2>Leitura crítica orientada</h2><ol><li>Seu paciente se parece com os participantes? Identifique a diferença que mais limita a extrapolação.</li><li>Qual desfecho orientou o cálculo amostral? Os demais foram confirmatórios ou exploratórios?</li><li>O estimando incorpora interrupções? Como foram tratados dados ausentes e resgate?</li><li>Qual benefício absoluto importa ao paciente? Compare custo e tolerabilidade no mesmo horizonte.</li><li>Abra o artigo e o suplemento antes de utilizar detalhes de subgrupos ou métodos que esta síntese não cobre.</li></ol><h2>Fontes e artigo original</h2>${refs(s.refs)}<div class="panel"><h3>O que foi consultado</h3>${s.refs.map(id=>`<p><strong>${e(sourceMap[id]?.title||id)}</strong><br>${e(sourceMap[id]?.note||'')}</p>`).join('')}</div><h2>Seu parecer sobre o artigo</h2><button class="btn small" data-worksheet="${e(id)}">Adicionar roteiro às minhas notas</button>${noteBox('estudo/'+id)}</article><aside class="panel toc"><div class="eyebrow">Clube de revista</div><p>Uma síntese para orientar a leitura do original. Não é reprodução do artigo.</p>${bookmark('estudo/'+id)}<button class="btn small full" data-ask="Destrinche o estudo ${e(s.name)} e explique suas limitações." style="margin-top:12px">Discutir com o tutor ✧</button><button class="btn small full" data-action="print" style="margin-top:12px">Imprimir / salvar PDF</button></aside></div>`}
function drugList(){return head('Consulta farmacológica','Medicamentos & apresentações','Doses de adultos e diferenças que importam. Referência regulatória indicada em cada ficha.')+`<div class="notice">${e(meta.regulatory)}</div><div class="module-grid">${drugs.map(x=>`<a class="module" href="#farmaco/${x.id}"><div class="row">${tag(x.group)}</div><h3>${e(x.name)}</h3><p>${e(x.brands)}</p><div class="module-footer"><span>${e(x.start)}</span><span>↗</span></div></a>`).join('')}</div><div class="section-head"><h2>Comparação rápida</h2></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Início adulto</th><th>Manutenção / limite</th></tr></thead><tbody>${drugs.map(x=>`<tr><td><a href="#farmaco/${x.id}">${e(x.brands)}</a></td><td>${e(x.start)}</td><td>${e(x.maintenance)}</td></tr>`).join('')}</tbody></table></div>`}
function drugPage(id){const x=drugs.find(x=>x.id===id);if(!x)return missing();const rows=[['Indicação educacional',x.use],['Dose inicial',x.start],['Titulação',x.titration],['Manutenção',x.maintenance],['Dose esquecida',x.missed],['Administração',x.administration],['Cuidados específicos',x.safety],['Rim e fígado',x.renal],['Armazenamento',x.storage]];return `<div class="content-grid"><article class="article"><div class="row">${btn('← Medicamentos','#farmacos','small')}${tag(x.group)}</div><h1>${e(x.name)}</h1><p class="lead">${e(x.brands)}</p>${tag(x.region,'gold')}<div class="notice">${e(meta.regulatory)}</div>${rows.map(([k,v])=>`<h2>${k}</h2><p>${e(v)}</p>`).join('')}<div class="notice info"><strong>Conferência antes de prescrever</strong><p>Nome comercial, concentração, dispositivo, via, frequência, indicação e idade. Não converter mg em cliques ou unidades; não somar doses perdidas.</p></div><h2>Informação do produto</h2>${refs(x.refs)}${noteBox('farmaco/'+id)}</article><aside class="panel toc"><div class="eyebrow">Uso seguro</div><p>Ficha educacional de adultos. Não gera receita e não calcula dose individual.</p>${bookmark('farmaco/'+id)}<button class="btn small full" data-ask="Explique a titulação e os cuidados de ${e(x.name)}." style="margin-top:12px">Perguntar ao tutor ✧</button><button class="btn small full" data-action="print" style="margin-top:12px">Imprimir / salvar PDF</button></aside></div>`}
function protocolList(){return head('Raciocínio organizado','Protocolos clínicos','Checklists educacionais, da consulta inicial à intercorrência. Não substituem avaliação individual.')+filters(protocols)+`<div class="module-grid">${filtered(protocols).map((x,i)=>`<a class="module" href="#protocolo/${x.id}"><div class="row">${tag(x.category,x.category==='Urgência'?'red':'')}</div><h3>${e(x.title)}</h3><p>${e(x.intro)}</p><div class="module-footer"><span>${x.steps.length} pontos de conferência</span><span>Abrir ↗</span></div></a>`).join('')}</div>`}
function protocolPage(id){const p=protocols.find(x=>x.id===id);if(!p)return missing();return `<article class="article">${btn('← Protocolos','#protocolos','small')}<h1>${e(p.title)}</h1><p class="lead">${e(p.intro)}</p><div class="notice"><strong>Ponto de atenção</strong><br>${e(p.stop)}</div><div class="panel checklist">${p.steps.map((s,i)=>`<label><input type="checkbox" aria-label="Conferir etapa ${i+1}"><span><strong>${i+1}.</strong> ${e(s)}</span></label>`).join('')}</div><p class="saved-note">Checklist temporário para estudo; não salva dados de paciente.</p>${refs(p.refs)}<div class="reading-actions">${bookmark('protocolo/'+id)}<button class="btn" data-action="print">Imprimir / salvar PDF</button></div>${noteBox('protocolo/'+id)}</article>`}
function casesList(){return head('Aprender aplicando','Casos & avaliação','Situações fictícias com alternativas comentadas. Sem certificação profissional.')+`<section class="feature"><div class="eyebrow">Teste seus conhecimentos</div><h2>Da leitura ao raciocínio.</h2><p>${questions.length} questões sobre mecanismos, doses, segurança e interpretação de estudos. Feedback imediato em cada resposta.</p><div class="feature-foot">${btn('Começar avaliação →','#quiz','lime')}</div></section><div class="section-head"><h2>Casos clínicos comentados</h2></div><div class="module-grid">${cases.map((c,i)=>`<a class="module" href="#caso/${c.id}"><div class="module-top"><span class="module-num">${String(i+1).padStart(2,'0')}</span>${tag(c.topic)}</div><h3>${e(c.title)}</h3><p>${e(c.profile)}</p><div class="module-footer"><span>${state.answers['case-'+c.id]!==undefined?'Caso respondido':'Caso fictício'}</span><span>Resolver ↗</span></div></a>`).join('')}</div>`}
function answerOptions(q,choice,kind){return q.options.map((o,i)=>`<button class="answer ${choice!==undefined?(i===q.correct?'correct':i===choice?'incorrect':''):''}" data-${kind}="${i}" ${choice!==undefined?'disabled':''}><strong>${String.fromCharCode(65+i)}.</strong> ${e(o)}${choice!==undefined&&i===q.correct?' ✓':''}</button>`).join('')}
function casePage(id){const c=cases.find(x=>x.id===id);if(!c)return missing();const choice=state.answers['case-'+id];return `<article class="article">${btn('← Casos','#casos','small')}<h1>${e(c.title)}</h1>${tag('Caso fictício · '+c.topic)}<div class="notice info">${e(c.profile)}</div><h2>${e(c.prompt)}</h2>${answerOptions(c,choice,'case-answer')}${choice!==undefined?`<section class="feedback" role="status"><strong>${choice===c.correct?'Resposta correta.':'Vamos revisar o raciocínio.'}</strong><p>${e(c.explanation)}</p><h3>O próximo passo</h3><p>${e(c.next)}</p>${refs(c.refs)}<button class="btn small" data-reset-case="${id}">Refazer caso</button></section>`:''}</article>`}
function quizPage(){if(!quizSession)quizSession={index:0,answers:{},order:[...questions].sort(()=>Math.random()-.5)};const ss=quizSession;if(ss.index>=ss.order.length){const score=ss.order.filter(x=>ss.answers[x.id]===x.correct).length;return head('Avaliação concluída',`${score} de ${ss.order.length} respostas corretas`,'Revise especialmente os pontos de segurança e os limites de interpretação.')+`<div class="panel"><p>Este resultado mede a compreensão das questões desta edição. Não confere título ou habilitação.</p><button class="btn primary" data-action="restart-quiz">Fazer nova avaliação</button></div>${ss.order.filter(x=>ss.answers[x.id]!==x.correct).map(x=>`<div class="reference"><strong>${e(x.prompt)}</strong><p>${e(x.explanation)}</p>${refs(x.refs)}</div>`).join('')}`}const q=ss.order[ss.index],choice=ss.answers[q.id];return `<article class="article">${btn('← Casos & avaliação','#casos','small')}<div class="section-head"><span class="eyebrow">Questão ${ss.index+1} de ${ss.order.length}</span>${tag(q.topic)}</div><div class="progress-track"><div style="width:${ss.index/ss.order.length*100}%"></div></div><h1 style="font-size:29px">${e(q.prompt)}</h1>${answerOptions(q,choice,'quiz-answer')}${choice!==undefined?`<section class="feedback" role="status"><strong>${choice===q.correct?'Correto.':'Revise este ponto.'}</strong><p>${e(q.explanation)}</p>${refs(q.refs)}<button class="btn primary" data-action="next-question">${ss.index===ss.order.length-1?'Ver resultado':'Próxima questão →'}</button></section>`:''}<p class="saved-note">Avaliação atual permanece nesta sessão; respostas mais recentes são salvas no caderno.</p></article>`}
function flashPage(){const due=cards.filter(c=>!state.reviews[c.id]||state.reviews[c.id].due<=Date.now());const c=cards.find(x=>x.id===flashId&&due.some(d=>d.id===x.id))||due[0];flashId=c?.id;return head('Retenção de conhecimento','Revisão espaçada','Tente responder antes de virar o cartão. O intervalo aumenta quando você lembra.')+`<div class="row" style="margin-bottom:22px">${tag(due.length+' para revisar')}${tag(Object.keys(state.reviews).length+' cartões já vistos')}</div>${c?`<article class="article"><button class="flashcard" data-action="flip" aria-label="${flipped?'Mostrar pergunta':'Mostrar resposta'}"><small>${flipped?'RESPOSTA COMENTADA':'RECUPERE DA MEMÓRIA'}</small><span>${e(flipped?c.back:c.front)}</span><small>${flipped?'Avalie sua lembrança abaixo':'Toque para revelar a resposta'}</small></button>${flipped?`<div class="reading-actions"><button class="btn" data-review="again">Não lembrei · 10 min</button><button class="btn" data-review="hard">Com esforço · 1 dia</button><button class="btn primary" data-review="good">Lembrei · ${nextReview('good',state.reviews[c.id]?.interval).interval} dias</button></div>${refs(c.refs)}`:''}</article>`:`<div class="empty"><h2>Revisão em dia.</h2><p>Os cartões voltarão conforme os intervalos programados.</p>${btn('Continuar estudando','#trilhas','primary')}</div>`}`}
function toolsPage(){const today=new Date().toISOString().slice(0,10);return head('Ferramentas de estudo','Números que fazem sentido','Cálculos educacionais transparentes. Nenhuma ferramenta gera prescrição individual.')+`<div class="two"><section class="panel"><h3>Risco absoluto & NNT</h3><p>Insira riscos acumulados no mesmo período. Não coloque HR nestes campos.</p><form id="risk-form"><div class="two"><label class="field">Risco no controle (%)<input name="control" type="number" min="0" max="100" step="any" value="8" required></label><label class="field">Risco no tratamento (%)<input name="treatment" type="number" min="0" max="100" step="any" value="6.5" required></label></div><button class="btn primary">Calcular</button></form><div id="risk-result" aria-live="polite"></div><small class="muted">NNT = 1 / ARR em proporção. Aproximação bruta; não ajusta censura ou tempo até evento.</small></section><section class="panel"><h3>IMC & variação de peso</h3><p>Use valores fictícios para explorar a interpretação.</p><form id="body-form"><label class="field">Altura (cm)<input name="height" type="number" min="100" max="250" step="any" value="170" required></label><div class="two"><label class="field">Peso inicial (kg)<input name="initial" type="number" min="25" max="500" step="any" value="100" required></label><label class="field">Peso atual (kg)<input name="current" type="number" min="25" max="500" step="any" value="90" required></label></div><button class="btn primary">Calcular</button></form><div id="body-result" aria-live="polite"></div></section></div><section class="panel"><h3>Visualizador de titulação</h3><p>Ilustra o esquema inicial da bula. Não recomenda dose e não incorpora tolerância, contraindicações ou pausas.</p><form id="schedule-form"><div class="two"><label class="field">Esquema<select name="drug">${Object.entries(schedules).map(([id,s])=>`<option value="${id}">${e(s.label)}</option>`).join('')}</select></label><label class="field">Data ilustrativa de início<input type="date" name="start" value="${today}" required></label></div><button class="btn primary">Visualizar etapas</button></form><div id="schedule-result" aria-live="polite"></div><div class="notice">A data não autoriza escalonamento. Tirzepatida e Ozempic param aqui no primeiro degrau de manutenção; aumentos posteriores são individualizados. Semaglutida 7,2 mg não integra este simulador.</div></section><section class="panel"><h3>Custo de continuidade</h3><p>Informe seu custo real. A ferramenta não busca preços e não infere quantas doses uma caneta contém.</p><form id="cost-form"><div class="two"><label class="field">Custo efetivo por dose (R$)<input type="number" name="cost" min="0" max="100000" step="any" required></label><label class="field">Frequência<select name="frequency"><option value="weekly">Semanal</option><option value="daily">Diária</option></select></label></div><button class="btn primary">Estimar continuidade</button></form><div id="cost-result" aria-live="polite"></div><small class="muted">Estimativa proporcional em manutenção; exclui titulação, desperdício, consultas, exames e mudanças de preço.</small></section>`}
function library(){return head('Transparência editorial','Referências & glossário','Fontes primárias e documentos regulatórios, com o nível de consulta identificado.')+`<section class="panel"><h3>Método e limites desta edição</h3><p>Consulta das fontes: ${meta.reviewed}. Priorizamos artigos fundamentais e informações oficiais EMA/FDA. Cada análise distingue interpretação clínica, limitações e acesso ao original. Alguns resumos/integrais não puderam ser acessados; nesses casos, a ficha identifica conferência regulatória complementar.</p><p>${e(meta.editorial)} ${e(meta.regulatory)}</p><p>Não é revisão sistemática, cobertura exaustiva da literatura ou curso acreditado. Não houve revisão médica independente. Dados de ensaios não são recomendações para todos os pacientes. O conteúdo não é atualizado automaticamente.</p><p>Atualização prioritária: bulas brasileiras por apresentação, marcas novas, registros de 2026, artigos completos e suplementos das leituras regulatórias. Relatos de imprensa não foram usados como base para doses.</p></section><div class="section-head"><h2>${sources.length} referências e documentos</h2></div>${sources.map((s,i)=>`<div class="reference" id="ref-${s.id}"><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${i+1}. ${e(s.title)} ↗</a><small>${e(s.note)}</small></div>`).join('')}<div class="section-head"><h2>Glossário</h2></div><div class="table-wrap"><table><thead><tr><th>Termo</th><th>Como interpretar</th></tr></thead><tbody>${glossary.map(([a,b])=>`<tr><td>${e(a)}</td><td>${e(b)}</td></tr>`).join('')}</tbody></table></div>`}
function notebook(){const saved=state.bookmarks.map(id=>idx.find(x=>x.url==='#'+id)).filter(Boolean);const notes=Object.entries(state.notes).filter(([,v])=>v.trim());return head('Sua memória de estudo','Meu caderno','Aulas concluídas, favoritos e notas. Os dados ficam neste navegador.',`<button class="btn" data-action="export">Exportar progresso</button>`)+`<div class="stats"><div class="stat"><strong>${state.completed.length}</strong><span>Aulas concluídas</span></div><div class="stat"><strong>${saved.length}</strong><span>Favoritos</span></div><div class="stat"><strong>${notes.length}</strong><span>Anotações</span></div><div class="stat"><strong>${Object.keys(state.reviews).length}</strong><span>Cartões revisados</span></div></div><div class="two"><section><h2 style="font-size:20px">Favoritos</h2>${saved.length?saved.map(x=>`<div class="reference"><a href="${x.url}">${e(x.title)}</a><small>${x.type}</small></div>`).join(''):`<div class="empty">Salve aulas, estudos e fichas para voltar a eles.</div>`}</section><section><h2 style="font-size:20px">Anotações</h2>${notes.length?notes.map(([id,n])=>`<div class="reference"><a href="#${e(id)}">${e(idx.find(x=>x.url==='#'+id)?.title||id)}</a><p style="white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7">${e(n)}</p></div>`).join(''):`<div class="empty">Abra uma aula e registre uma ideia no campo de notas.</div>`}</section></div><section class="panel" style="margin-top:28px"><h3>Leve seu progresso para outro navegador</h3><p>Exporte um arquivo de backup e importe aqui. A importação substitui os dados locais após confirmação.</p><label class="field">Importar backup JSON<input type="file" id="import-file" accept="application/json,.json"></label></section>`}
function tutorPage(){return head('Assistente de aprendizagem','Tutor IA','Perguntas sobre o conteúdo, leitura crítica e conceitos. Não envie dados identificáveis de pacientes.')+`<div class="content-grid"><section><div class="panel"><div class="row">${tag('OpenAI · integração preparada')}${tag(apiReady===true?'Disponível':apiReady===false?'Aguardando ativação':'Verificando disponibilidade',apiReady?'':'gold')}</div><p>O tutor seleciona trechos da biblioteca antes de responder. A resposta deve informar fontes e incertezas; confirme qualquer orientação clínica nos documentos originais.</p><div id="chat" class="chat" aria-live="polite">${chat.length?chat.map(m=>`<div class="message ${m.role}">${e(m.text)}${m.refs?refs(m.refs):''}</div>`).join(''):`<div class="message">Que parte você quer compreender melhor? Você pode pesquisar a biblioteca mesmo sem ativar a IA.</div>`}</div><form id="chat-form"><label class="field">Sua pergunta<textarea name="question" maxlength="2000" placeholder="Ex.: Por que o SURPASS-CVOT não demonstra superioridade?" required></textarea></label><label class="field">Código de acesso do tutor<input type="password" name="access" autocomplete="off" placeholder="Código definido pelo responsável pela plataforma"></label><div class="row"><button class="btn primary" type="submit" ${chatBusy?'disabled':''}>${chatBusy?'Consultando…':'Perguntar à IA ✧'}</button><button class="btn" type="button" data-action="local-search">Pesquisar na biblioteca</button><button class="btn small" type="button" data-action="clear-chat">Limpar conversa</button></div></form><div id="tutor-local-results"></div></div></section><aside><section class="panel"><h3>Comece por uma pergunta</h3><ul class="compact-list">${['Compare SELECT e SURMOUNT-5.','Explique risco relativo e NNT.','Quais cuidados na titulação de tirzepatida?','Como diferenciar retinopatia e NOIA-NA?'].map(q=>`<li><button class="btn small full" data-prompt="${e(q)}">${e(q)}</button></li>`).join('')}</ul></section><section class="panel"><h3>Sobre a ativação</h3><p>As aulas e ferramentas funcionam sem IA. O tutor precisa de uma chave da API OpenAI no servidor e um código de acesso para proteger o uso.</p><p>A assinatura do ChatGPT não ativa automaticamente esta integração. A plataforma não inclui cobrança automática ou armazenamento de prontuários.</p><p>Esta versão no Sites é estática. A função do tutor está preparada para Netlify.</p></section></aside></div>`}
function historyPage(){return head('Perspectiva histórica','Uma ideia que mudou de escala','Do eixo intestino–pâncreas aos ensaios de desfechos metabólicos.',btn('Voltar à trilha','#trilhas'))+`<article class="article"><div class="timeline">${timeline.map(([year,title,text])=>`<section class="timeline-item"><div class="eyebrow">${e(year)}</div><h2 style="margin:8px 0">${e(title)}</h2><p>${e(text)}</p></section>`).join('')}</div>${refs(['physiology','byetta','leader','select','surmount5'])}</article>`}
function missing(){return `<div class="empty"><h1>Conteúdo não encontrado</h1><p>Escolha um item da trilha ou faça uma busca.</p>${btn('Voltar ao início','#inicio','primary')}</div>`}
function render(){const [r,id]=route.split('/');const pages={inicio:dashboard,trilhas:trail,aula:()=>lessonPage(id),farmacos:drugList,farmaco:()=>drugPage(id),estudos:studyList,estudo:()=>studyPage(id),protocolos:protocolList,protocolo:()=>protocolPage(id),casos:casesList,caso:()=>casePage(id),quiz:quizPage,revisao:flashPage,ferramentas:toolsPage,tutor:tutorPage,biblioteca:library,caderno:notebook,historia:historyPage};shell((pages[r]||missing)());document.title=`${nav.find(x=>x[0]===group(r))?.[1]||'Aprender'} · Incretina`;bindPage();if(r==='tutor'&&apiReady===null)checkApi()}
function navigate(){let next;try{next=decodeURIComponent(location.hash.slice(1))||'inicio'}catch{next='inicio'};if(next.startsWith('sec-'))return;if(next!==route){filter='Todos';route=next;mobile=false;flipped=false;render();window.scrollTo({top:0});document.querySelector('#main')?.focus({preventScroll:true})}}
function bindGlobal(){document.querySelector('#global-search').addEventListener('input',ev=>{const q=ev.target.value,box=document.querySelector('#search-results');if(q.trim().length<2){box.classList.add('hide');return}const results=searchContent(q,idx);box.innerHTML=results.length?results.map(x=>`<a href="${x.url}"><small>${x.type}</small>${e(x.title)}</a>`).join(''):'<div style="padding:16px;font-size:14px">Nenhum resultado. Tente outro termo.</div>';box.classList.remove('hide')});document.querySelector('#search-form').addEventListener('submit',ev=>{ev.preventDefault();document.querySelector('#search-results a')?.click()});document.querySelector('#global-search').addEventListener('keydown',ev=>{if(ev.key==='Escape')document.querySelector('#search-results').classList.add('hide')});document.querySelectorAll('[data-note]').forEach(t=>t.addEventListener('input',()=>{state.notes[t.dataset.note]=t.value;persist()}))}
root.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;if(b.dataset.worksheet){const s=studies.find(x=>x.id===b.dataset.worksheet);if(!s)return;const id='estudo/'+s.id;state.notes[id]=(state.notes[id]?state.notes[id]+'\n\n':'')+worksheet(s.name);state.notes[id]=state.notes[id].slice(0,20000);persist();render();document.querySelector('[data-note]')?.focus();return}if(b.dataset.scroll){ev.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.complete){const id=b.dataset.complete;state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];persist();render();return}if(b.dataset.bookmark){const id=b.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();b.textContent=state.bookmarks.includes(id)?'★ Salvo no caderno':'☆ Salvar no caderno';return}if(b.dataset.ask){sessionStorage.setItem('incretina-prompt',b.dataset.ask);location.hash='tutor';return}if(b.dataset.prompt){document.querySelector('[name=question]').value=b.dataset.prompt;document.querySelector('[name=question]').focus();return}if(b.dataset.caseAnswer!==undefined){const id=route.split('/')[1];if(state.answers['case-'+id]!==undefined)return;state.answers['case-'+id]=Number(b.dataset.caseAnswer);persist();render();return}if(b.dataset.resetCase){delete state.answers['case-'+b.dataset.resetCase];persist();render();return}if(b.dataset.quizAnswer!==undefined){const q=quizSession.order[quizSession.index];if(quizSession.answers[q.id]!==undefined)return;quizSession.answers[q.id]=Number(b.dataset.quizAnswer);state.answers[q.id]=Number(b.dataset.quizAnswer);persist();render();return}if(b.dataset.review){state.reviews[flashId]=nextReview(b.dataset.review,state.reviews[flashId]?.interval);persist();flashId=null;flipped=false;render();return}switch(b.dataset.action){case'menu':mobile=!mobile;document.querySelector('.sidebar').classList.toggle('open',mobile);b.setAttribute('aria-expanded',String(mobile));break;case'print':window.print();break;case'next-question':quizSession.index++;render();window.scrollTo({top:0});break;case'restart-quiz':quizSession=null;render();break;case'flip':flipped=!flipped;render();break;case'export':downloadBackup();break;case'local-search':localTutorSearch();break;case'clear-chat':chat=[];render();break}});
document.addEventListener('click',ev=>{if(!ev.target.closest('.search'))document.querySelector('#search-results')?.classList.add('hide');if(mobile&&!ev.target.closest('.sidebar')&&!ev.target.closest('[data-action=menu]')){mobile=false;document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){mobile=false;document.querySelector('.sidebar')?.classList.remove('open')}});
function bindPage(){document.querySelector('#risk-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),r=calcRisk(Number(f.get('control')),Number(f.get('treatment')));document.querySelector('#risk-result').innerHTML=!r?'<div class="notice">Use riscos de 0 a 100%.</div>':`<div class="notice info"><strong>${r.harm?'Aumento':'Redução'} absoluta: ${fmt(Math.abs(r.difference),2)} pp</strong><br>${r.nnt?`${r.harm?'NNH':'NNT'} aproximado: ${r.nnt}`:'Sem diferença absoluta: NNT não finito.'}<br>${r.relative!==null?`${r.harm?'Aumento':'Redução'} relativa de risco: ${fmt(Math.abs(r.relative))}%`:'Risco de controle zero: redução relativa indefinida.'}<br>Mesmo período e população dos riscos informados. Não é um cálculo de HR.</div>`});document.querySelector('#body-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),r=calcBody(Number(f.get('height')),Number(f.get('initial')),Number(f.get('current')));document.querySelector('#body-result').innerHTML=r?`<div class="notice info"><strong>IMC atual: ${fmt(r.bmi)} kg/m²</strong><br>${r.loss>=0?'Perda':'Ganho'}: ${fmt(Math.abs(r.loss))}% (${fmt(Math.abs(r.kg))} kg).<br>O cálculo não determina indicação, dose ou composição corporal.</div>`:'<div class="notice">Revise os valores informados.</div>'});document.querySelector('#schedule-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),id=f.get('drug'),rows=makeSchedule(id,f.get('start'));document.querySelector('#schedule-result').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Período ilustrativo</th><th>Dose do esquema</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.from)} a ${date(r.to)}</td><td>${fmt(r.dose,2)} ${e(r.unit)}</td></tr>`).join('')}</tbody></table></div>${refs(schedules[id].refs)}`:'<div class="notice">Escolha uma data válida.</div>'});document.querySelector('#cost-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),cost=Number(f.get('cost')),daily=f.get('frequency')==='daily';if(!Number.isFinite(cost)||cost<0||cost>100000)return;document.querySelector('#cost-result').innerHTML=`<div class="notice info"><strong>28 dias: R$ ${fmt(cost*(daily?28:4),2)}</strong><br>30 dias, proporcional: R$ ${fmt(cost*(daily?30:30/7),2)}<br>12 semanas: R$ ${fmt(cost*(daily?84:12),2)}</div>`});document.querySelector('#import-file')?.addEventListener('change',importBackup);document.querySelector('#chat-form')?.addEventListener('submit',sendChat);if(route==='tutor'){const prompt=sessionStorage.getItem('incretina-prompt');if(prompt){document.querySelector('[name=question]').value=prompt;sessionStorage.removeItem('incretina-prompt')}const ch=document.querySelector('#chat');if(ch)ch.scrollTop=ch.scrollHeight}}
function downloadBackup(){const blob=new Blob([JSON.stringify({schema:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='incretina-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exportado. Guarde-o para restaurar seu progresso.')}
async function importBackup(ev){const file=ev.target.files?.[0];if(!file)return;try{if(file.size>2e6)throw Error();const data=JSON.parse(await file.text());if(data.schema!==1||!data.data||typeof data.data!=='object')throw Error();const s=data.data;const allowed=new Set(idx.map(x=>x.url.slice(1)));if(!Array.isArray(s.completed)||!Array.isArray(s.bookmarks)||!s.notes||typeof s.notes!=='object'||!s.reviews||typeof s.reviews!=='object'||!s.answers||typeof s.answers!=='object')throw Error();const cleaned=blank();cleaned.completed=[...new Set(s.completed.filter(x=>lessons.some(l=>l.id===x)))];cleaned.bookmarks=[...new Set(s.bookmarks.filter(x=>allowed.has(x)))];for(const [k,v]of Object.entries(s.notes))if(allowed.has(k)&&typeof v==='string'&&v.length<=20000)cleaned.notes[k]=v;for(const [k,v]of Object.entries(s.reviews))if(cards.some(c=>c.id===k)&&v&&Number.isFinite(v.due)&&Number.isFinite(v.interval)&&v.interval>=0&&v.interval<=60)cleaned.reviews[k]={due:v.due,interval:v.interval};for(const [k,v]of Object.entries(s.answers))if((questions.some(q=>q.id===k)||cases.some(c=>'case-'+c.id===k))&&Number.isInteger(v)&&v>=0&&v<4)cleaned.answers[k]=v;if(lessons.some(l=>l.id===s.last))cleaned.last=s.last;if(!confirm('Substituir o progresso deste navegador pelo backup selecionado?'))return;state=cleaned;persist();render();toast('Progresso restaurado.')}catch{toast('Arquivo inválido. Use um backup JSON exportado pela Incretina.')}}
function localTutorSearch(){const q=document.querySelector('[name=question]').value.trim();const results=searchContent(q,idx,6);let related=results;if(!related.length){const terms=normalize(q).split(/\W+/).filter(t=>t.length>4);related=idx.map(x=>({...x,score:terms.reduce((n,t)=>n+(normalize(x.title+' '+x.text).includes(t)?1:0),0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score).slice(0,6)}document.querySelector('#tutor-local-results').innerHTML=`<h3 style="margin-top:28px">Busca local · sem resposta de IA</h3>${related.length?related.map(x=>`<div class="reference"><a href="${x.url}">${e(x.title)}</a><small>${x.type}</small></div>`).join(''):'<div class="empty">Tente um termo mais específico, como “tirzepatida”, “SELECT” ou “gestação”.</div>'}`}
async function checkApi(){try{const r=await fetch('/api/tutor',{headers:{Accept:'application/json'}});if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error();const d=await r.json();apiReady=r.ok&&d.ready===true}catch{apiReady=false}if(route==='tutor'&&!chatBusy){const q=document.querySelector('[name=question]')?.value||'';render();document.querySelector('[name=question]').value=q}}
async function sendChat(ev){ev.preventDefault();if(chatBusy)return;const f=new FormData(ev.target),question=String(f.get('question')).trim(),access=String(f.get('access'));if(!question)return;if(apiReady!==true){toast('A IA ainda não está ativada neste ambiente. A busca na biblioteca está disponível.');localTutorSearch();return}chatBusy=true;chat.push({role:'user',text:question});render();try{const r=await fetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json','X-Tutor-Access':access},body:JSON.stringify({question}),signal:AbortSignal.timeout(55000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível consultar a IA.');chat.push({role:'assistant',text:d.answer,refs:d.sources})}catch(err){chat.push({role:'assistant',text:err.name==='TimeoutError'?'A consulta demorou mais que o esperado. Tente novamente.':String(err.message||'Falha na consulta.')})}finally{chatBusy=false;render()}}
window.addEventListener('hashchange',navigate);navigate();

function journalPanel(s){const j=journal[s.id];if(!j)return '';return `<section class="panel journal-panel"><div class="eyebrow">Discussão aprofundada</div><h2>${e(j.question)}</h2><p>Formule sua resposta antes de abrir o comentário.</p><details><summary>Comparar com o raciocínio comentado</summary><p>${e(j.answer)}</p></details><h3>Para discutir com colegas</h3><p>${e(j.discussion)}</p><small class="muted">Exercício autoral de interpretação. Consulte as fontes abaixo para conferir métodos e números.</small></section>`}
